# AUTOGENERATED KERNEL (LLM)
# Source: LLM-generated candidate implementation
# Status: Experimental / uncurated
# Expectation: Correctness-first, performance not representative

import torch
import torch.nn as nn
import triton
import triton.language as tl


def get_autotune_configs():
    configs = []
    for block_size in [1024, 2048]:
        configs.append(
            triton.Config(
                {"BLOCK_SIZE": block_size},
            )
        )
    return configs


@triton.autotune(
    configs=get_autotune_configs(),
    key=["N_COLS"],
)
@triton.jit
def mse_row_kernel(
    pred_ptr,
    target_ptr,
    row_sums_ptr,
    N_ROWS,
    N_COLS,
    stride_pred_row,
    stride_pred_col,
    stride_target_row,
    stride_target_col,
    BLOCK_SIZE: tl.constexpr,
):
    row_idx = tl.program_id(0)

    pred_row_start = pred_ptr + row_idx * stride_pred_row
    target_row_start = target_ptr + row_idx * stride_target_row

    acc = 0.0

    for col_start in tl.range(0, N_COLS, BLOCK_SIZE):
        cols = col_start + tl.arange(0, BLOCK_SIZE)
        mask = cols < N_COLS

        pred_vals = tl.load(
            pred_row_start + cols * stride_pred_col, mask=mask, other=0.0
        ).to(tl.float32)
        target_vals = tl.load(
            target_row_start + cols * stride_target_col, mask=mask, other=0.0
        ).to(tl.float32)

        diff = pred_vals - target_vals
        acc += tl.sum(diff * diff, axis=0)

    tl.store(row_sums_ptr + row_idx, acc)


class Model(nn.Module):
    def __init__(self):
        super(Model, self).__init__()

    def forward(self, predictions, targets):
        predictions = predictions.contiguous()
        targets = targets.contiguous()

        N_ROWS, N_COLS = predictions.shape

        row_sums = torch.empty(N_ROWS, device=predictions.device, dtype=torch.float32)

        grid = (N_ROWS,)
        mse_row_kernel[grid](
            predictions,
            targets,
            row_sums,
            N_ROWS,
            N_COLS,
            predictions.stride(0),
            predictions.stride(1),
            targets.stride(0),
            targets.stride(1),
        )

        return torch.sum(row_sums) / (N_ROWS * N_COLS)
